CREATE      VIEW [CE].[vwEnrolments] AS

	SELECT 
	 [ENR ID]
	,[Enrolment Name]
	,[Created Datetime]
	,[Created Date]
	,[Created By]
	,[End Date]
	,[Application Type ID]
	,[Application Type]
	,[Contact No]
	,[Contact ID]
	,[Election Date]
	,CASE WHEN [Enrolment Date] < '1980-01-01' THEN '1980-01-01' ELSE [Enrolment Date] END AS 'Enrolment Date'
	,CASE WHEN [Enrolment Date] < '1980-01-01' THEN 1980 ELSE YEAR([Enrolment Date]) END AS 'Enrolment Year'
	,[Number of Attempts]
	,expected_final_date AS 'Expected Final Date'
	,[Enrolment Local Group ID]
	,[Pathway ID]
	,[Pathway]
	,[Route ID]
	,[Route]
	,[Enrolment Type ID]
	,[Enrolment Type]
	,[Outcome ID]
	,[Outcome]
	,[State Code]
	,[State]
	,[Status Code]
	,[Status]
	,[apuk_ricsrecordid]
	,[ARC Assessment Status]
	,[Approved By Counsellor]
	,[Competency Selection Completed Date]
	,[Case Study Status]
	,[Case Study Feedback]
	,[Summary of Experience Status]
	,[Summary of Experience Feedback]
	,[Preliminary Submission Received]
	,[Submission Received]
	,[apuk_corporateenrolment] AS [Corporate Enrolment]
	,[apuk_highestprofessionalbody]
	,[apuk_highestprofessionalbodylookup]
	,[apuk_highestprofessionalbodylookup_entitytype]
	,[apuk_highestprofessionalbodylookupname]
	,[apuk_highestqualification]
	,[apuk_firstqualifiedlocalgroup]
	,[apuk_firstqualifiedlocalgroupname]
	,[apuk_applicationreceiveddate]
	,[apuk_enrolmentdeclarationaccepted]
	,[apuk_iscounsellorunknown] 
	,[apuk_requestedcounsellor]
	,[apuk_requestedcounsellornotified]
	,[apuk_requestedcounselloraccepted]
	,[apuk_candidatenotifiedofcounsellordecision]

	FROM [synapse_ce].[vwEnrolments]
